export default function Sidebar({ setPage }) {
  return (
    <div className="w-64 bg-[#0b0b0b] text-white p-6">
      <h1 className="text-yellow-400 font-bold text-xl mb-10">
        Bodyzeal Admin
      </h1>

      <button onClick={() => setPage("enquiries")}
        className="block w-full text-left mb-4 hover:text-yellow-400">
        ENQUIRIES
      </button>

      <button onClick={() => setPage("reviews")}
        className="block w-full text-left mb-4 hover:text-yellow-400">
        REVIEWS
      </button>

      <button onClick={() => setPage("gallery")}
        className="block w-full text-left hover:text-yellow-400">
        GALLERY
      </button>
    </div>
  );
}
